$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type @"
using System;using System.Runtime.InteropServices;public class S360OpenLoginHistory{[DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr hWnd);[DllImport("user32.dll")]public static extern bool SetCursorPos(int X,int Y);[DllImport("user32.dll")]public static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra);}
"@
$ws=New-Object -ComObject WScript.Shell;$null=$ws.AppActivate('Society360');$ws.SendKeys('{F5}');Start-Sleep -Seconds 2
$root=[System.Windows.Automation.AutomationElement]::RootElement;$wins=$root.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$w=$wins|Where-Object {$_.Current.Name -like '*Society360*Google Chrome'}|Select-Object -First 1;if(!$w){throw 'Society360 Chrome window missing'};$null=[S360OpenLoginHistory]::SetForegroundWindow([IntPtr]$w.Current.NativeWindowHandle);[S360OpenLoginHistory]::SetCursorPos(150,640)|Out-Null;for($i=0;$i -lt 5;$i++){[S360OpenLoginHistory]::mouse_event(0x0800,0,0,[uint32]4294967176,[UIntPtr]::Zero);Start-Sleep -Milliseconds 100}
$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$login=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Login / Session Audit' -and -not $_.Current.IsOffscreen}|Select-Object -First 1
if(!$login){$parent=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Audit & Governance' -and -not $_.Current.IsOffscreen}|Select-Object -First 1;if(!$parent){throw 'Audit & Governance menu parent not visible'};$r=$parent.Current.BoundingRectangle;[S360OpenLoginHistory]::SetCursorPos([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2))|Out-Null;[S360OpenLoginHistory]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[S360OpenLoginHistory]::mouse_event(4,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 400;for($i=0;$i -lt 4;$i++){[S360OpenLoginHistory]::SetCursorPos(150,640)|Out-Null;[S360OpenLoginHistory]::mouse_event(0x0800,0,0,[uint32]4294967176,[UIntPtr]::Zero);Start-Sleep -Milliseconds 100};$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$login=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Login / Session Audit' -and -not $_.Current.IsOffscreen}|Select-Object -First 1}
if(!$login){throw 'Login / Session Audit leaf is not visible'};try{$login.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()}catch{$r=$login.Current.BoundingRectangle;[S360OpenLoginHistory]::SetCursorPos([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2))|Out-Null;[S360OpenLoginHistory]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[S360OpenLoginHistory]::mouse_event(4,0,0,0,[UIntPtr]::Zero)};Start-Sleep -Seconds 2
$root=[System.Windows.Automation.AutomationElement]::RootElement;$wins=$root.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$w=$wins|Where-Object {$_.Current.Name -like '*Society360*Google Chrome'}|Select-Object -First 1;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$rows=@($all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::DataItem -and $_.Current.Name -match '^\d{1,2}/\d{1,2}/\d{2},'});$empty=$all|Where-Object {$_.Current.Name -eq 'No login history records found.' -and -not $_.Current.IsOffscreen}|Select-Object -First 1;$search=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and $_.Current.Name -eq 'Search user / IP / status'}|Select-Object -First 1;Write-Output 'LOGIN_HISTORY_VISIBLE_UI=OPEN';Write-Output ('SEARCH_INPUT='+[bool]$search);Write-Output ('EMPTY_STATE='+[bool]$empty);Write-Output ('ROW_COUNT_VISIBLE='+$rows.Count)
